<script>
const API_ENDPOINT = "http://localhost:11434/webhook/obsidian-api";
const DRIVE_IMPORT_ENDPOINT = "http://localhost:11434/webhook/obsidian-drive-import";
let STATE = window.__INITIAL_STATE__ || { boards: [], cards: [], expenses: [], budgets: [], jobs: [], notes: [], flashcards: [] };
let activeBoardId = (STATE.boards[0] && STATE.boards[0].board_id) || "brd-projects";
let activeMobileCol = "";
let currentFcIndex = 0;
let fcShowAnswer = false;
let selectedNoteId = (STATE.notes[0] && STATE.notes[0].note_id) || "";

// ============================================================================
// 1. GOOGLE OAUTH 2.0 SECURITY GATE
// ============================================================================
function checkSavedOAuthSession() {
  try {
    const raw = localStorage.getItem("obsidian_second_brain_oauth");
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed.authenticated && parsed.email) {
        document.getElementById("oauthGateOverlay").classList.add("unlocked");
        document.getElementById("syncStatusText").textContent = "🟢 Signed in as " + parsed.email;
        return true;
      }
    }
  } catch (e) {}
  return false;
}

async function handleGoogleOAuthCallback(response) {
  const errEl = document.getElementById("gateErrorMsg");
  errEl.style.color = "#a78bfa";
