// 3. GOOGLE DRIVE SHORTCUT & SOURCE DOCUMENT EXTRACTOR
// ============================================================================
async function syncDriveShortcutsNow() {
  const box = document.getElementById("driveExtractStatusBox");
  if (box) box.textContent = "⏳ Scanning Google Drive Vault Drop-Folders & resolving shortcuts...";
  showToast("Scanning Google Drive folders & shortcuts...");
  try {
    const res = await fetch(DRIVE_IMPORT_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "scan_all_folders" })
    });
    const data = await res.json();
    if (data && data.state) {
      STATE = data.state;
      renderAll();
    }
    const cnt = (data && data.extracted_count) || 0;
    const msg = cnt > 0
      ? `✅ Extracted ${cnt} document(s) from Google Drive into your Obsidian Vault!`
      : `✅ Drive folders scanned (0 new shortcuts/docs found yet — drop any Google Doc/Sheet shortcut into your Drive folders to auto-extract).`;
    if (box) box.textContent = msg;
    showToast(msg);
  } catch (e) {
    if (box) box.textContent = "Error: " + e.message;
    showToast("Drive sync error: " + e.message, true);
  }
}

async function extractSingleGoogleDocUrl() {
  const url = document.getElementById("importDocUrl").value.trim();
  const folder = document.getElementById("importTargetFolder").value;
  const title = document.getElementById("importDocTitle").value.trim();
  if (!url) return showToast("Paste a Google Doc or Google Sheet URL first", true);

  const box = document.getElementById("driveExtractStatusBox");
  box.textContent = `⏳ Extracting document from Google Drive into ${folder}...`;
  try {
    const res = await fetch(DRIVE_IMPORT_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ doc_url: url, target_folder: folder, doc_title: title })
    });
    const data = await res.json();
    if (data && data.state) {
      STATE = data.state;
      renderAll();
    }
    document.getElementById("importDocUrl").value = "";
    document.getElementById("importDocTitle").value = "";
    box.textContent = `✅ Extracted & saved into ${folder}!`;
    showToast(`Loaded into ${folder}!`);
  } catch (e) {
    box.textContent = "Error: " + e.message;
    showToast("Failed: " + e.message, true);
  }
}

