function renderKanbanTab() {
  if (!STATE.boards.find(b => b.board_id === activeBoardId) && STATE.boards[0]) {
    activeBoardId = STATE.boards[0].board_id;
  }
  document.getElementById("boardSelectorBar").innerHTML = STATE.boards.map(b => {
    const cnt = STATE.cards.filter(c => c.board_id === b.board_id && !c.completed).length;
    return `<button class="board-pill ${b.board_id === activeBoardId ? 'active' : ''}" onclick="activeBoardId='${esc(b.board_id)}'; activeMobileCol=''; renderKanbanTab();">${esc(b.title)} (${cnt})</button>`;
  }).join("");

  const board = STATE.boards.find(b => b.board_id === activeBoardId);
  const container = document.getElementById("kanbanColumnsContainer");
  const stagePills = document.getElementById("mobileKanbanStagePills");
  if (!board) {
    container.innerHTML = "";
    stagePills.innerHTML = "";
    return;
  }
  const cols = Array.isArray(board.columns_json) ? board.columns_json : JSON.parse(board.columns_json || '["To Do","In Progress","Done"]');
  if (!activeMobileCol || !cols.includes(activeMobileCol)) activeMobileCol = cols[0];

  const isMobile = document.body.classList.contains("mobile-view-mode");
  const boardCards = STATE.cards.filter(c => c.board_id === board.board_id);

  if (isMobile) {
    stagePills.style.display = "flex";
    stagePills.innerHTML = cols.map(c => {
      const cnt = boardCards.filter(x => x.column_name === c).length;
      return `<button class="board-pill ${c === activeMobileCol ? 'active' : ''}" onclick="activeMobileCol='${esc(c)}'; renderKanbanTab();">${esc(c)} (${cnt})</button>`;
    }).join("");
  } else {
    stagePills.style.display = "none";
  }

  const visibleCols = isMobile ? [activeMobileCol] : cols;
  container.innerHTML = visibleCols.map(col => {
    const colIdx = cols.indexOf(col);
    const prevCol = colIdx > 0 ? cols[colIdx - 1] : null;
    const nextCol = colIdx < cols.length - 1 ? cols[colIdx + 1] : null;
    const cList = boardCards.filter(c => c.column_name === col);

    const cardsHtml = cList.map(c => `
      <div class="k-card ${c.completed ? 'completed' : ''}">
        <div class="k-card-top">
          <input type="checkbox" ${c.completed ? 'checked' : ''} style="width:15px; height:15px;" onchange="toggleCard('${esc(c.card_id)}')" />
          <div class="k-card-title">${esc(c.title)}</div>
        </div>
        ${c.description ? `<div class="k-card-desc">${esc(c.description)}</div>` : ''}
        <div class="k-card-actions">
          <div style="display:flex; gap:4px;">
            ${prevCol ? `<button class="btn btn-sm" onclick="moveCard('${esc(c.card_id)}','${esc(prevCol)}')">◀ ${isMobile ? esc(prevCol) : ''}</button>` : ''}
            ${nextCol ? `<button class="btn btn-sm" onclick="moveCard('${esc(c.card_id)}','${esc(nextCol)}')">${isMobile ? esc(nextCol) + ' ' : ''}▶</button>` : ''}
          </div>
          <div style="display:flex; gap:4px;">
            <button class="btn btn-sm" onclick="openCardModal('${esc(c.card_id)}')">✏️</button>
            <button class="btn btn-danger btn-sm" onclick="deleteCard('${esc(c.card_id)}')">🗑️</button>
          </div>
        </div>
      </div>
    `).join("");

    return `
      <div class="kanban-col">
        <div class="kanban-col-header">
          <span class="kanban-col-title">${esc(col)}</span>
          <span class="kanban-count">${cList.length}</span>
        </div>
        <div>${cardsHtml || `<div style="font-size:11.5px; color:var(--text-muted); padding:6px 0;">Empty column</div>`}</div>
        <button class="btn btn-sm" style="width:100%; justify-content:center; margin-top:6px;" onclick="openCardModal('','${esc(board.board_id)}','${esc(col)}')">+ Add to ${esc(col)}</button>
      </div>
    `;
  }).join("");
}

