const files = driveResp.files || [];

const FOLDER_ID_TO_VAULT = {
  "1jywRhW-FSaiIVYTKa3mUuJAVDsk3h6KT": "01_Job_Hunt",
  "1EfilzHYQ-Zg-r1seaB0JgSNH4Z9PQfGu": "02_Projects",
  "1SyqTbIVMPZ2-wkey4OzYXreNgL5uUexf": "03_Expenses",
  "1wrM6f1u-f4koeq9veX0sZ9Vj1A1slTpk": "04_Education",
  "1lbO8mh_OvPTtfmkqpUXXgopFe6vk5ptx": "05_Business_Ideas",
  "18re_fKgdbvuE7rwPuC4v8UXS6-6moeMA": "06_LouLou_And_Luxe"
};

const queue = [];

// 1. Process all files & shortcuts inside the 6 Google Drive Vault Drop-Folders
for (const f of files) {
  if (f.mimeType === 'application/vnd.google-apps.folder') continue;
  const parentId = (f.parents && f.parents[0]) || '';
  const vaultFolder = FOLDER_ID_TO_VAULT[parentId] || '04_Education';

  let targetId = f.id;
  let targetMime = f.mimeType;
  let isShortcut = false;

  if (f.mimeType === 'application/vnd.google-apps.shortcut' && f.shortcutDetails) {
    targetId = f.shortcutDetails.targetId;
    targetMime = f.shortcutDetails.targetMimeType;
    isShortcut = true;
  }

  let exportUrl = '';
  let sourceKind = 'doc';
  if (targetMime === 'application/vnd.google-apps.document') {
    exportUrl = `https://www.googleapis.com/drive/v3/files/${targetId}/export?mimeType=text/plain`;
    sourceKind = 'google-doc';
  } else if (targetMime === 'application/vnd.google-apps.spreadsheet') {
    exportUrl = `https://www.googleapis.com/drive/v3/files/${targetId}/export?mimeType=text/csv`;
    sourceKind = 'google-sheet';
  } else if (targetMime && (targetMime.startsWith('text/') || targetMime === 'application/json')) {
    exportUrl = `https://www.googleapis.com/drive/v3/files/${targetId}?alt=media`;
    sourceKind = 'text-file';
  }

  if (exportUrl && targetId) {
    queue.push({
      json: {
        skipExport: false,
        fileId: f.id,
        targetId,
        title: String(f.name || 'Imported Document').replace(/\.(md|txt|csv|xlsx|docx)$/i, ''),
        vaultFolder,
        isShortcut,
        sourceKind,
        exportUrl,
        webViewLink: f.webViewLink || (sourceKind === 'google-sheet'
          ? `https://docs.google.com/spreadsheets/d/${targetId}/edit`
          : `https://docs.google.com/document/d/${targetId}/edit`)
      }
    });
  }
}

// 2. Also handle a direct Google Doc / Google Sheet URL or ID pasted in the App UI!
const rawUrl = String(body.doc_url || '').trim();
if (rawUrl) {
  const mId = rawUrl.match(/\/d\/([a-zA-Z0-9_\-]{15,})/) || rawUrl.match(/id=([a-zA-Z0-9_\-]{15,})/) || [null, rawUrl];
  const directId = mId[1] ? mId[1].trim() : '';
  if (directId && directId.length >= 15) {
    const isSheet = rawUrl.toLowerCase().includes('spreadsheet') || String(body.source_type || '').toLowerCase() === 'sheet';
    const sourceKind = isSheet ? 'google-sheet' : 'google-doc';
    const exportUrl = isSheet
      ? `https://www.googleapis.com/drive/v3/files/${directId}/export?mimeType=text/csv`
      : `https://www.googleapis.com/drive/v3/files/${directId}/export?mimeType=text/plain`;
    const targetFolder = String(body.target_folder || '04_Education').trim();
    const customTitle = String(body.doc_title || '').trim() || (isSheet ? 'Imported Google Sheet' : 'Imported Google Doc');

    queue.push({
      json: {
        skipExport: false,
        fileId: directId,
        targetId: directId,
        title: customTitle,
        vaultFolder: targetFolder,
        isShortcut: false,
        sourceKind,
        exportUrl,
        webViewLink: isSheet
          ? `https://docs.google.com/spreadsheets/d/${directId}/edit`
          : `https://docs.google.com/document/d/${directId}/edit`
      }
    });
  }
}

if (queue.length === 0) {
  return [{
    json: {
      skipExport: true,
      exportUrl: 'https://www.googleapis.com/drive/v3/about?fields=user'
    }
  }];
}

return queue;

const metaItems = $('Code: Resolve Shortcuts & Build Export Queue').all();
const exportedItems = $input.all();

function sqlStr(val) {
  if (val === null || val === undefined) return "''";
  return "'" + String(val).replace(/'/g, "''") + "'";
}
function safeFileSlug(s) {
  return String(s || 'Note').replace(/[^A-Za-z0-9_\- ]+/g, '').trim().replace(/\s+/g, '_').slice(0, 55) || 'Note';
}

function parseCsvLine(line) {
  const out = [];
  let cur = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') {
        cur += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (ch === ',' && !inQuotes) {
      out.push(cur.trim());
      cur = '';
    } else {
      cur += ch;
    }
  }
  out.push(cur.trim());
  return out;
}

function csvToMarkdownTable(csvText) {
  const lines = String(csvText || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  if (lines.length === 0) return '_Empty Google Sheet_';
  const rows = lines.slice(0, 150).map(parseCsvLine);
  const colCount = Math.max(...rows.map(r => r.length), 1);
  const norm = r => {
    const copy = r.slice(0, colCount).map(c => String(c || '').replace(/\|/g, '\\|'));
    while (copy.length < colCount) copy.push('');
    return copy;
  };
  const header = norm(rows[0]);
  const sep = header.map(() => '---');
  const mdLines = [
    '| ' + header.join(' | ') + ' |',
    '| ' + sep.join(' | ') + ' |'
  ];
  for (let i = 1; i < rows.length; i++) {
    mdLines.push('| ' + norm(rows[i]).join(' | ') + ' |');
  }
  return mdLines.join('\n');
}

let sqlStatements = '';
const extractedSummary = [];

for (let i = 0; i < metaItems.length; i++) {
  const meta = metaItems[i].json;
  if (meta.skipExport) continue;

  const rawResp = exportedItems[i] ? exportedItems[i].json : {};
  let rawContent = '';
  if (typeof rawResp === 'string') {
    rawContent = rawResp;
  } else if (rawResp && typeof rawResp.data === 'string') {
    rawContent = rawResp.data;
  } else if (rawResp && !rawResp.error) {
    rawContent = JSON.stringify(rawResp, null, 2);
  }

  if (!rawContent || (rawResp && rawResp.error)) continue;

  const nid = 'gdrive-' + String(meta.targetId).replace(/[^A-Za-z0-9_\-]/g, '').slice(0, 40);
  const folder = meta.vaultFolder || '04_Education';
  const title = meta.title || 'Google Drive Document';
  const filePath = `${folder}/${safeFileSlug(title)}.md`;
  const nowIso = new Date().toISOString();

  let bodyMd = '';
  if (meta.sourceKind === 'google-sheet') {
    bodyMd = csvToMarkdownTable(rawContent);
  } else {
    bodyMd = String(rawContent).replace(/^\uFEFF/, '').trim();
  }

  const fullMd = [
    '---',
    `title: "${title.replace(/"/g, '')}"`,
    `folder: "${folder}"`,
    `source_type: "${meta.sourceKind}"`,
    `is_shortcut: ${meta.isShortcut ? 'true' : 'false'}`,
    `source_drive_id: "${meta.targetId}"`,
    `source_url: "${meta.webViewLink}"`,
    `synced_at: "${nowIso}"`,
    '---',
    '',
    `# 📄 ${title}`,
    '',
    `> [!NOTE] Synced from Google Drive (${meta.isShortcut ? 'via Drive Shortcut' : 'Direct Source'})`,
    `> - **Target Vault Folder:** \`${folder}\` | **Source Link:** [Open Original in Google Docs/Sheets](${meta.webViewLink})`,
    '',
    bodyMd,
    ''
  ].join('\n');

  sqlStatements += `
    INSERT INTO obsidian_notes (note_id, folder, title, file_path, tags, content_md, pinned, updated_at)
    VALUES (${sqlStr(nid)}, ${sqlStr(folder)}, ${sqlStr(title)}, ${sqlStr(filePath)}, '#gdrive-sync #${folder.toLowerCase()}', ${sqlStr(fullMd)}, TRUE, NOW())
    ON CONFLICT (note_id) DO UPDATE SET
      folder = EXCLUDED.folder,
      title = EXCLUDED.title,
      file_path = EXCLUDED.file_path,
      content_md = EXCLUDED.content_md,
      updated_at = NOW();
  `;

  extractedSummary.push({
    note_id: nid,
    title,
    folder,
    file_path: filePath,
    source_kind: meta.sourceKind,
    is_shortcut: meta.isShortcut,
    source_url: meta.webViewLink
  });
}

const fullSql = sqlStatements + `
SELECT
  (SELECT COALESCE(json_agg(t), '[]'::json) FROM (SELECT * FROM obsidian_kanban_boards ORDER BY title ASC) t) AS boards,
  (SELECT COALESCE(json_agg(t), '[]'::json) FROM (SELECT * FROM obsidian_kanban_cards ORDER BY position ASC, updated_at DESC) t) AS cards,
  (SELECT COALESCE(json_agg(t), '[]'::json) FROM (SELECT * FROM obsidian_expenses ORDER BY tx_date DESC, updated_at DESC) t) AS expenses,
  (SELECT COALESCE(json_agg(t), '[]'::json) FROM (SELECT * FROM obsidian_budgets ORDER BY category ASC) t) AS budgets,
  (SELECT COALESCE(json_agg(t), '[]'::json) FROM (SELECT * FROM obsidian_job_dossiers ORDER BY updated_at DESC) t) AS jobs,
  (SELECT COALESCE(json_agg(t), '[]'::json) FROM (SELECT * FROM obsidian_notes ORDER BY folder ASC, pinned DESC, updated_at DESC) t) AS notes,
  (SELECT COALESCE(json_agg(t), '[]'::json) FROM (SELECT * FROM obsidian_flashcards ORDER BY due_date ASC) t) AS flashcards;
`;

return [{
  json: {
    extracted_count: extractedSummary.length,
    extracted_files: extractedSummary,
    sql: fullSql
  }
}];

const importMeta = $('Code: Format Extracted Markdown & Upsert SQL').first().json;
const dbRow = $input.last().json || {};

let bridgeRes = { ok: true };
try {
  bridgeRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://obsidian-vault-bridge:3080/vault/compile',
    body: { push_github: true, commit_msg: `Synced ${importMeta.extracted_count} Google Drive Shortcut/Doc(s) to Vault` },
    json: true,
    timeout: 25000
  });
} catch (e) {
  bridgeRes = { ok: false, error: e.message };
}

return [{
  json: {
    ok: true,
    extracted_count: importMeta.extracted_count,
    extracted_files: importMeta.extracted_files,
    state: {
      boards: dbRow.boards || [],
      cards: dbRow.cards || [],
      expenses: dbRow.expenses || [],
      budgets: dbRow.budgets || [],
      jobs: dbRow.jobs || [],
      notes: dbRow.notes || [],
      flashcards: dbRow.flashcards || []
    },
    vault_sync: bridgeRes
  }
}];

let backupData = { files: [] };
try {
  backupData = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://obsidian-vault-bridge:3080/vault/git-backup',
    body: { commit_msg: 'Automated Cloud Vault & Drive Sync' },
