} catch (e) {}

const files = backupData.files || [];
let masterMd = '# 🧠 Obsidian Second Brain — Complete Cloud Vault Mirror\nUpdated: ' + new Date().toISOString() + '\n\n';
let snapJson = '{}';

for (const f of files) {
  if (f.name && f.name.endsWith('.md')) {
