  }
  if (f.path === '_DB_Snapshots/postgres_vault_snapshot.json') {
    snapJson = f.content;
  }
}

return [
  {
    json: {
      fileId: '1YErj_9iQFng5nPkShp0ISMuxvjm47rn_',
      fileName: 'Obsidian_Vault_Master_Bundle.md'
    },
    binary: {
      data: {
        data: Buffer.from(masterMd, 'utf8').toString('base64'),
        mimeType: 'text/markdown',
        fileName: 'Obsidian_Vault_Master_Bundle.md'
      }
    }
  },
  {
    json: {
      fileId: '1LbkfZOBYzh1cB_E3vDIjMRCiMMK-JteT',
      fileName: 'postgres_vault_snapshot.json'
    },
    binary: {
      data: {
        data: Buffer.from(snapJson, 'utf8').toString('base64'),
